void tq_expire_first(struct timer_queue *tq) {
    if (tq->count == 0) return;

    struct timer_entry *te = tq->timers[0];

    for (int i = 0; i < tq->count - 1; i++)
        tq->timers[i] = tq->timers[i + 1];
    tq->timers[tq->count - 1] = NULL;
    tq->count--;

    /* Save state to stack before freeing */
    int saved_id = te->id;
    char saved_name[32];
    strncpy(saved_name, te->callback_name, 31);
    saved_name[31] = '\0';

    free(te);

    printf("firing timer %d: %s\n", saved_id, saved_name);
}
